create table outbound_mail_queue (max_retries integer not null, retry_count integer not null, sent_subdirectory integer, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, next_retry_at timestamp(6) with time zone not null, processing_started_at timestamp(6) with time zone, sent_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, status varchar(20) not null check (status in ('PENDING','PROCESSING','SENT','PARTIAL_SUCCESS','FAILED','CANCELLED')), processor_id varchar(100), subject varchar(1000), attachments_json LONGTEXT, body_html LONGTEXT, body_text LONGTEXT, failed_domains_json TEXT, last_error TEXT, message_id varchar(255), recipients_json TEXT not null, sender_address varchar(255) not null, sent_domains_json TEXT, sent_file_name varchar(255), primary key (id));
create index idx_queue_status_retry on outbound_mail_queue (status, next_retry_at);
create index idx_queue_sender on outbound_mail_queue (sender_address);
create index idx_queue_created on outbound_mail_queue (created_at);
create index idx_queue_sent_file on outbound_mail_queue (sent_file_name);
